// Validates the payload and maps it to Airtable field names.
// Runs even though the Vercel function validates too: replays and
// any other caller reach this webhook without passing through Vercel.

const body = $('Webhook').first().json.body ?? {};
const cfg = $('Config').first().json;

const errors = [];
const check = (ok, message) => { if (!ok) errors.push(message); };
const isNonEmpty = (v) => typeof v === 'string' && v.trim().length > 0;
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

const contact = body.contact ?? {};
const consent = body.consent ?? {};
const attribution = body.attribution ?? {};
const context = body.context ?? {};

check(UUID.test(body.lead_id ?? ''), 'lead_id must be a UUID');
check(UUID.test(body.event_id ?? ''), 'event_id must be a UUID');
check(isNonEmpty(contact.first_name), 'contact.first_name is required');
check(isNonEmpty(contact.last_name), 'contact.last_name is required');
check(/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test((contact.email ?? '').trim()), 'contact.email is invalid');
check(/^\+1\d{10}$/.test(contact.phone ?? ''), 'contact.phone must be E.164 (+1XXXXXXXXXX)');
check(/^\d{5}$/.test(contact.zip ?? ''), 'contact.zip must be 5 digits');
check(/^[A-Z]{2}$/.test(contact.state ?? ''), 'contact.state must be a two-letter code');
check(consent.given === true, 'consent.given must be true');
check(isNonEmpty(consent.text), 'consent.text is required');

if (errors.length > 0) {
  return [{ json: { valid: false, errors } }];
}

const restricted = cfg.restricted_states
  .split(',')
  .map((s) => s.trim().toUpperCase())
  .filter(Boolean);

const fields = {
  'Lead ID': body.lead_id,
  'Meta Event ID': body.event_id,
  'Submitted At': body.submitted_at,
  'Received At': context.received_at ?? new Date().toISOString(),
  'First Name': contact.first_name.trim(),
  'Last Name': contact.last_name.trim(),
  'Email': contact.email.trim().toLowerCase(),
  'Phone': contact.phone,
  'ZIP': contact.zip,
  'State': contact.state,
  'Qualification Status': body.quiz?.qualified ? 'Qualified' : 'Needs Review',
  'Quiz Answers': JSON.stringify(body.quiz?.answers ?? {}, null, 2),
  'Consent Given': true,
  'Consent Text': consent.text,
  'Consent Timestamp': consent.timestamp,
  'IP Address': context.ip,
  'User Agent': context.user_agent,
  'Page URL': attribution.page_url,
  'UTM Source': attribution.utm_source,
  'UTM Medium': attribution.utm_medium,
  'UTM Campaign': attribution.utm_campaign,
  'UTM Content': attribution.utm_content,
  'UTM Term': attribution.utm_term,
  'fbclid': attribution.fbclid,
  'fbc': attribution.fbc,
  'fbp': attribution.fbp,
  'Referrer': attribution.referrer,
  'Funnel Variant': attribution.variant,
  'CAPI Status': 'Pending',
  'Routing': restricted.includes(contact.state) ? 'Restricted State' : 'Standard',
  'Is Test': body.is_test === true,
  'Ingest Path': body.ingest_path === 'replay' ? 'Replay' : 'Live',
  'Raw Payload': JSON.stringify(body, null, 2),
};

// Omit empty values so a replay never blanks out existing data.
for (const key of Object.keys(fields)) {
  if (fields[key] === null || fields[key] === undefined || fields[key] === '') delete fields[key];
}

return [{ json: { valid: true, lead: body, fields } }];

// Builds the Meta Conversions API Lead event.
// PII is normalized, then SHA-256 hashed. IP, user agent, fbc and fbp
// are sent unhashed, as Meta requires. Quiz answers are never sent.

const crypto = require('crypto');

const lead = $('Validate Lead').first().json.lead;
const cfg = $('Config').first().json;
const contact = lead.contact;
const attribution = lead.attribution ?? {};
const context = lead.context ?? {};

const sha256 = (value) => crypto.createHash('sha256').update(value).digest('hex');
const hashed = (value) => (value ? [sha256(value)] : undefined);
const lower = (value) => (value ?? '').toString().trim().toLowerCase();

const userData = {
  em: hashed(lower(contact.email)),
  ph: hashed(contact.phone.replace(/\D/g, '')),
  fn: hashed(lower(contact.first_name).replace(/[^\p{L}]/gu, '')),
  ln: hashed(lower(contact.last_name).replace(/[^\p{L}]/gu, '')),
  st: hashed(lower(contact.state)),
  zp: hashed(contact.zip.slice(0, 5)),
  country: hashed('us'),
  external_id: hashed(lower(lead.lead_id)),
  client_ip_address: context.ip || undefined,
  client_user_agent: context.user_agent || undefined,
  fbc: attribution.fbc || undefined,
  fbp: attribution.fbp || undefined,
};
for (const key of Object.keys(userData)) {
  if (userData[key] === undefined) delete userData[key];
}

// Meta rejects future timestamps and events older than 7 days.
const submitted = Math.floor(Date.parse(lead.submitted_at) / 1000);
const now = Math.floor(Date.now() / 1000);
const eventTime = Number.isFinite(submitted) ? Math.min(submitted, now) : now;

const payload = {
  data: [
    {
      event_name: 'Lead',
      event_time: eventTime,
      event_id: lead.event_id,
      action_source: 'website',
      event_source_url: attribution.page_url,
      user_data: userData,
      custom_data: { funnel_variant: attribution.variant ?? undefined },
    },
  ],
};
if (cfg.meta_test_event_code) payload.test_event_code = cfg.meta_test_event_code;

return [{ json: { payload } }];

// Reduces an HTTP error to a short summary with credentials removed.
// Raw n8n HTTP errors include request headers (Authorization), and some
// APIs echo the token back in the message, so the raw error is never stored.

const REDACTIONS = [
  /Bearer\s+[^\s"'\\]+/gi,
  /\bEAA[A-Za-z0-9]{10,}[^\s"'\\]*/g,
  /\bpat[A-Za-z0-9]{10,}\.[A-Za-z0-9]+/g,
];
const redact = (text) => REDACTIONS.reduce((t, re) => t.replace(re, '[REDACTED]'), String(text ?? ''));

const err = $json.error ?? {};
let apiError = err.error;
if (typeof apiError === 'string') {
  try { apiError = JSON.parse(apiError); } catch { /* keep raw string */ }
}
if (apiError && typeof apiError === 'object' && 'error' in apiError) apiError = apiError.error;

const status = err.statusCode ?? err.status ?? err.httpCode;
const details = apiError && typeof apiError === 'object' ? apiError : {};
const message = typeof apiError === 'string' ? apiError : details.message ?? err.message ?? err.description ?? 'Unknown error';

const summary = redact(
  [
    status && `HTTP ${status}`,
    details.type,
    details.code !== undefined && `code ${details.code}`,
    message,
    details.fbtrace_id && `fbtrace_id ${details.fbtrace_id}`,
  ]
    .filter(Boolean)
    .join(' | '),
).slice(0, 1000);

const { error, ...rest } = $json;
return [{ json: { ...rest, error_summary: summary } }];

